            for pattern in local_patterns:
                dominated = False
                for other in local_patterns:
                    if other is pattern:
                        continue
                    if not bitmask_subset(other["used_mask"], pattern["used_mask"]):
                        continue
                    if other["gmin"] + FEAS_EPS < pattern["gmin"]:
